55: /**
56:  * Converts SubRip (.srt) subtitles to WebVTT (.vtt) format
57:  */
58: function convertSrtToVtt(srtText) {
59:   if (srtText.trim().startsWith('WEBVTT')) {
60:     return srtText;
61:   }
62:   // Replace comma in timestamps: 00:00:20,000 --> 00:00:24,400 to 00:00:20.000 --> 00:00:24.400
63:   const normalized = srtText.replace(
64:     /(\d{2}:\d{2}:\d{2}),(\d{3})/g,
65:     '$1.$2'
66:   );
67:   return `WEBVTT\n\n${normalized.trim()}\n`;
68: }
