115: /**
116:  * Executes request sealing in crush.wasm.
117:  * 
118:  * @param {WebAssembly.Instance} wasmInstance
119:  * @param {object} params
120:  * @param {string} params.server
121:  * @param {string} params.type - 'movie' | 'tv' | 'series'
122:  * @param {string|number} params.tmdbId
123:  * @param {string|number} [params.season]
124:  * @param {string|number} [params.episode]
125:  * @returns {{ responseKey: Buffer, keyId: number, ephemeralPublic: Buffer, ciphertextBody: Buffer }}
126:  */
127: function sealRequest(wasmInstance, { server, type, tmdbId, season, episode }) {
128:   const exports = wasmInstance.exports;
129:   const wasmType = (type === 'tv' || type === 'series') ? 'series' : 'movie';
130:   
131:   const payloadObj = { tmdb: String(tmdbId) };
132:   if (wasmType === 'series') {
133:     payloadObj.season = String(season || 1);
134:     payloadObj.episode = String(episode || 1);
135:   }
136: 
137:   const payloadJson = JSON.stringify({
138:     path: `/${server}/${wasmType}`,
139:     payload: payloadObj
140:   });
141: 
142:   const encodedPayload = Buffer.from(payloadJson, 'utf8');
143:   const randBytes = crypto.randomBytes(RANDOM_SEED_LEN);
144: 
145:   const payloadPtr = exports.alloc(encodedPayload.length);
146:   const randPtr = exports.alloc(randBytes.length);
147:   const outPtr = exports.alloc(OUT_BUF_MAX);
148: 
149:   const mem = new Uint8Array(exports.memory.buffer);
150:   mem.set(encodedPayload, payloadPtr);
151:   mem.set(randBytes, randPtr);
152: 
153:   const sealedLen = exports.seal_request(
154:     payloadPtr, encodedPayload.length,
155:     randPtr, randBytes.length,
156:     outPtr, OUT_BUF_MAX
157:   );
158: 
159:   if (sealedLen <= HEADER_LEN) {
160:     exports.dealloc(payloadPtr, encodedPayload.length);
161:     exports.dealloc(randPtr, randBytes.length);
162:     exports.dealloc(outPtr, OUT_BUF_MAX);
163:     throw new Error(`WASM seal_request returned invalid length: ${sealedLen}`);
164:   }
165: 
166:   const sealedBuffer = Buffer.from(exports.memory.buffer, outPtr, sealedLen);
167:   const responseKey = Buffer.from(sealedBuffer.subarray(0, AES_KEY_LEN));
168:   const keyId = sealedBuffer[AES_KEY_LEN];
169:   const ephemeralPublic = Buffer.from(sealedBuffer.subarray(AES_KEY_LEN + KEY_ID_LEN, HEADER_LEN));
170:   const ciphertextBody = Buffer.from(sealedBuffer.subarray(HEADER_LEN, sealedLen));
171: 
172:   // Free allocated linear memory
173:   exports.dealloc(payloadPtr, encodedPayload.length);
174:   exports.dealloc(randPtr, randBytes.length);
175:   exports.dealloc(outPtr, OUT_BUF_MAX);
176: 
177:   return { responseKey, keyId, ephemeralPublic, ciphertextBody };
178: }
